public sealed class WorkspaceService(InstallConfig config,CadClient cad) {
 public LibraryCatalog Catalog{get;}=new(config.ContentRoot);public bool Retired(string kind,string id)=>WarehousePaths.IsRetired(config.ContentRoot,kind,id);
 public CadClient Cad=>cad;public PlanFiles Plans{get;}=new(config.DataRoot);public ContentStore Store{get;}=new(config.ContentRoot);public DrawingIntelligence Intelligence{get;}=new(config);
 public TemplateProfile Template(string id)=>Store.Template(id);
 public bool SourceProfileCompatible(JObject profile, TemplateProfile template, SkillDefinition skill)
 {
  if((profile.Value<string>("templateId") is string tid && tid!=template.Id)||
     (profile.Value<string>("skillId") is string sid && sid!=skill.Id))
   return false;
  string tv=profile.Value<string>("templateVersion")??template.Version;
  string sv=profile.Value<string>("skillVersion")??skill.Version;
  if(tv==template.Version&&sv==skill.Version)
   return true;
  if(skill.Id!=ResidentialSourcePlan.SkillId)
   return false;
  // These settings only affect CAD placement. Reuse a draft when its
  // recognition resources are otherwise identical.
  try
  {
   JObject GeometryProfile(TemplateProfile value)
   {
    var obj=JObject.FromObject(value);
    obj.Remove("Version");
    (obj["Presets"] as JObject)?.Remove("doorFramePlacement");
    return obj;
   }
   JObject RecognitionProfile(SkillDefinition value)
   {
    var obj=JObject.FromObject(value);
    obj.Remove("Version");
    (obj["Parameters"] as JObject)?.Remove("axisMergeToleranceMm");
    return obj;
   }
   return (tv==template.Version||Json.Hash(GeometryProfile(Store.Template(template.Id,tv)))==Json.Hash(GeometryProfile(template)))&&
          (sv==skill.Version||Json.Hash(RecognitionProfile(Store.Skill(skill.Id,sv)))==Json.Hash(RecognitionProfile(skill)));
  }
  catch(Exception e) when(e is IOException or CadException){return false;}
 }
 public JObject SourceAnalysis(string id)
 {
  var model=Json.Read<JObject>(File.ReadAllText(Intelligence.AnalysisPath(id)));
  if(model["reviewMetadata"] is JObject profile&&profile.Value<string>("templateId") is string tid&&
     profile.Value<string>("skillId") is string sid)
  {
   try{model["draftProfileCompatible"]=SourceProfileCompatible(profile,Template(tid),Store.Skill(sid));}
   catch(Exception e) when(e is IOException or CadException){model["draftProfileCompatible"]=false;}
  }
  return model;
 }
 public List<object> Templates()=>Store.Ids("templates").Where(id=>!Retired("templates",id)&&!Catalog.Deleted("templates",id)).Select(id=>{var t=Store.Template(id);return (object)new{t.Id,Name=Catalog.Name("templates",id,t.Name),GroupId=Catalog.Label("templates",id).GroupId,t.Version,t.Units,hash=Json.Hash(t),blocks=t.Blocks.Select(b=>b.Id),layers=t.Layers.Select(l=>l.Name),versions=Store.Versions("templates",id),t.Presets};}).ToList();
 public List<object> Skills(){var result=new List<object>();foreach(string id in Store.Ids("skills").Where(id=>!Retired("skills",id)&&!Catalog.Deleted("skills",id))){try{var s=Store.Skill(id);var missing=s.RequiredTools.Except(Validation.Tools).ToArray();bool enabled=Store.Enabled(id);result.Add(new{s.Id,Name=Catalog.Name("skills",id,s.Name),GroupId=Catalog.Label("skills",id).GroupId,s.Version,Enabled=enabled,s.RequiredInputs,s.RequiredTools,s.TemplateId,s.Builder,s.Parameters,sourceCatalogPending=s.Recipe!=null&&s.Builder=="source"&&s.Recipe.AllowedBlocks.Count==0,versions=Store.Versions("skills",id),missingTools=missing,status=!enabled?"DISABLED":missing.Length>0?"DEPENDENCY_MISSING":"READY"});}catch(CadException e){result.Add(new{Id=id,status="INVALID",message=e.Message});}}return result;}
 public SkillDefinition ValidateSkill(SkillDefinition s){if(s.Parameters.TryGetValue("axisMergeToleranceMm",out double tol)&&(!double.IsFinite(tol)||tol<0||tol>100))throw new CadException("INVALID_AXES","Ngưỡng rà trùng trục phải từ 0 đến 100 mm.");Catalog.Available("templates",s.TemplateId);Json.Name(s.Id);if(s.RequiredTools==null||s.RequiredInputs==null||s.Workflow==null||!Version.TryParse(s.Version,out _)||string.IsNullOrWhiteSpace(s.Name)||s.Name.Length>120||s.Workflow.Count>100||s.RequiredInputs.Length>20||s.RequiredTools.Length>30)throw new CadException("INVALID_SKILL","Bounded versioned Skill metadata required.");foreach(string input in s.RequiredInputs)Json.Name(input);var missing=s.RequiredTools.Except(Validation.Tools).ToArray();if(missing.Length>0)throw new CadException("DEPENDENCY_MISSING",string.Join(", ",missing));if(!new[]{"workflow","source","custom"}.Contains(s.Builder)&&!ArchitectureBuilder.Builders.Contains(s.Builder))throw new CadException("UNSUPPORTED_BUILDER",s.Builder);if(s.Builder=="workflow"&&s.Workflow.Count<1)throw new CadException("INVALID_SKILL","Workflow steps required.");var t=Store.Template(s.TemplateId);Validation.Template(t);if(s.Recipe!=null)DraftingRules.Recipe(s.Recipe,t);foreach(var op in s.Workflow){if(!s.RequiredTools.Contains(op.Kind))throw new CadException("DEPENDENCY_MISSING","Workflow tool must be declared.");Validation.Operation(op,t,true);}return s;}
 public string HashHelper=>Path.Combine(Path.GetDirectoryName(config.HostExecutable)!,"HashCompat","AICad.HashCompat.exe");
 public void ImportSkill(SkillDefinition s){Catalog.Available("skills",s.Id);ValidateSkill(s);Store.Publish("skills",s.Id,s.Version,s,FrameworkPlanHash.ComputeValue(s,HashHelper,"skill"));}
 public List<string> TemplateConsumers(string id)=>Store.Ids("skills").Where(x=>!Catalog.Deleted("skills",x)&&Store.Skill(x).TemplateId==id).ToList();
 public void DemandTemplateImpact(TemplateProfile t){foreach(string id in TemplateConsumers(t.Id)){var skill=Store.Skill(id);if(skill.Recipe!=null)try{DraftingRules.Recipe(skill.Recipe,t);}catch(CadException e){throw new CadException("DEPENDENCY_IMPACT","Skill "+id+": "+e.Message);}foreach(var op in skill.Workflow)try{Validation.Operation(op,t,true);}catch(CadException e){throw new CadException("DEPENDENCY_IMPACT","Skill "+id+" cần tài nguyên đã bị đổi/xóa: "+e.Message);}}}
 public void ImportTemplate(TemplateProfile t){Catalog.Available("templates",t.Id);Validation.Template(t);DemandTemplateImpact(t);foreach(var appearance in t.Layers.Select(l=>l.Appearance).Where(a=>a?.SourceHash!=""&&a?.SourceHash!=null)){string file=Path.Combine(WarehousePaths.Folder(config.ContentRoot,"content-assets"),appearance!.SourceHash+".dwg");if(!File.Exists(file)||Json.FileHash(file)!=appearance.SourceHash)throw new CadException("MISSING_ASSET","Thiếu nguồn bộ layer.");}foreach(var b in t.Blocks.Where(b=>b.NativeSource!=null)){string file=Path.Combine(WarehousePaths.Folder(config.ContentRoot,"content-assets"),b.NativeSource!.FileHash+".dwg");if(!File.Exists(file)||Json.FileHash(file)!=b.NativeSource.FileHash)throw new CadException("MISSING_ASSET","Thiếu DWG nguồn của block "+b.Id);}Store.Publish("templates",t.Id,t.Version,t,FrameworkPlanHash.ComputeValue(t,HashHelper,"template"));}
 public void Activate(string kind,string id,string version){Catalog.Available(kind,id);if(kind=="templates"){var t=Store.Template(id,version);Validation.Template(t);DemandTemplateImpact(t);}else if(kind=="skills")ValidateSkill(Store.Skill(id,version));else throw new CadException("INVALID_KIND",kind);Store.Activate(kind,id,version);}

 public void SetSkill(string id,bool enabled){Catalog.Available("skills",id);if(enabled)ValidateSkill(Store.Skill(id));Store.SetEnabled(id,enabled);}
 public async Task<List<TaskInfo>> Scan(string session,string document,string revision,CancellationToken ct=default){var tasks=(await cad.Call(session,"scan_task_blocks",document,revision,cancellation:ct)).ToObject<List<TaskInfo>>()!;TaskGraph.Order(tasks);return tasks;}
 public List<PlanRecord> History(){Directory.CreateDirectory(Path.Combine(config.DataRoot,"plans"));return Directory.EnumerateFiles(Path.Combine(config.DataRoot,"plans"),"*.json").Select(f=>{try{return Json.Read<PlanRecord>(File.ReadAllText(f));}catch{return null;}}).Where(p=>p!=null).OrderByDescending(p=>p!.UpdatedUtc).Take(300).Select(p=>p!).ToList();}
 async Task<(DrawingPlan,TaskInfo,SkillDefinition)> Base(string session,string document,string revision,string taskId,JObject input,CancellationToken ct){var tasks=await Scan(session,document,revision,ct);var task=tasks.SingleOrDefault(t=>t.TaskId==taskId)??throw new CadException("TASK_NOT_FOUND","Task no longer exists.");if(task.Warnings.Count>0)throw new CadException("INVALID_TASK",string.Join("; ",task.Warnings));foreach(string dep in task.Dependencies){var prior=History().FirstOrDefault(h=>h.Status=="DONE"&&h.Plan.TaskId==dep&&h.Plan.DocumentId==document&&h.Plan.SessionId==session)??throw new CadException("DEPENDENCY_PENDING","Waiting for "+dep);var check=await cad.Call(session,"inspect_execution",document,revision,new(){["planId"]=prior.Plan.PlanId},ct);if(check.Value<string>("status")!="PRESENT")throw new CadException("DEPENDENCY_STALE","Dependency receipt or outputs no longer exist: "+dep);}
 Catalog.Available("skills",task.SkillId);var skill=ValidateSkill(Store.Skill(task.SkillId,input.Value<string>("_skillVersion")));if(!Store.Enabled(skill.Id))throw new CadException("SKILL_DISABLED",skill.Id);var template=Store.Template(task.TemplateId.Length>0?task.TemplateId:skill.TemplateId,input.Value<string>("_templateVersion"));Catalog.Available("templates",template.Id);if(template.Id!=skill.TemplateId)throw new CadException("TEMPLATE_MISMATCH","Task and Skill template must match.");var plan=new DrawingPlan{SessionId=session,DocumentId=document,DocumentRevision=revision,TaskId=task.TaskId,TaskHandle=task.Handle,SkillId=skill.Id,SkillVersion=skill.Version,SkillHash=Json.Hash(skill),Template=template,TemplateHash=Json.Hash(template),Scope=TaskPlacement.OutputScope(task),TaskScope=task.OutputPoint==null?null:task.Scope,OutputPoint=task.OutputPoint};return(plan,task,skill);}
 public async Task<PlanRecord> CreatePlan(string session,string document,string revision,string taskId,JObject input,CancellationToken ct=default){var(plan,task,skill)=await Base(session,document,revision,taskId,input,ct);foreach(string key in skill.RequiredInputs)if(input[key]==null)throw new CadException("NEEDS_INPUT","Missing confirmed input: "+key);
 if(skill.Builder=="source"){string id=input.Value<string>("sourceId")??"";if(!Guid.TryParseExact(id,"N",out _))throw new CadException("SOURCE_REQUIRED","Chọn bản dự thảo nguồn đã gắn với khung trước khi lập kế hoạch.");if(task.TaskId.StartsWith("IMG_",StringComparison.Ordinal)&&task.TaskId!="IMG_"+id.Substring(0,8))throw new CadException("SOURCE_TASK_MISMATCH","Nguồn đã chọn không khớp khung trong DWG.");var sourceModel=Json.Read<JObject>(File.ReadAllText(Intelligence.AnalysisPath(id)));DrawingIntelligence.DemandDraft(skill.Id,sourceModel);plan.Operations=Intelligence.Map(id,input,out var binding,out string hash);plan.Sources.Add(binding);plan.SourceModelHash=hash;plan.Assumptions.Add("Image-derived trial plan: overall footprint confirmed; internal geometry is approximate and requires human review.");if(sourceModel["reviewMetadata"]?.Value<bool?>("requiresCatalogReview")==true){
  if(skill.Id!=ResidentialSourcePlan.SkillId||input.Value<bool?>("allowPartial")!=true)
   throw new CadException("CATALOG_REVIEW_REQUIRED","Chọn triển khai phần đã sẵn sàng hoặc duyệt danh mục block trước.");
  var omitted=plan.Operations.Where(o=>o.Kind=="insert_block"&&skill.Recipe?.AllowedBlocks.Contains(o.AssetId)!=true).ToArray();
  plan.Operations.RemoveAll(omitted.Contains);
  foreach(var group in omitted.GroupBy(o=>o.AssetId))
   plan.Assumptions.Add($"Bỏ qua {group.Count()} block {group.Key} chờ duyệt; giữ các khoảng hở tường từ bản nháp.");
 }if(sourceModel["reviewMetadata"] is JObject profile&&!SourceProfileCompatible(profile,plan.Template,skill))throw new CadException("SOURCE_LIBRARY_CHANGED","Nguồn đã được dựng bằng phiên bản thư viện khác; kiểm tra và dựng lại nguồn trước.");if(skill.Recipe?.IncludeAxes==true){var axes=DraftingRules.Axes(skill.Recipe);double dx=1000-sourceModel["bounds"]!.Value<double>("minX"),dy=1000-sourceModel["bounds"]!.Value<double>("minY");foreach(var axis in axes)foreach(var point in axis.Points){point.X+=dx;point.Y+=dy;}plan.Operations.AddRange(axes);}if(sourceModel["assumptions"] is JArray notes)plan.Assumptions.AddRange(notes.Values<string>().Where(x=>x!=null).Select(x=>x!).Take(40));if(skill.Id==ResidentialSourcePlan.SkillId&&skill.Recipe!=null){if(AiOperationDefaults.UseCatalogWindowDepth(plan.Operations,plan.Template))plan.Assumptions.Add("Cửa sổ dùng chiều sâu khung DT theo cấu hình Template.");if(sourceModel["reviewMetadata"]?.Value<string>("method")=="APP_AI_IMAGE_PLAN")AiOperationDefaults.FitEstimatedWindowWidths(plan);ResidentialSourcePlan.Complete(plan,skill,skill.Recipe,input,task);}Place(plan,task,false);if(skill.Id==ResidentialSourcePlan.SkillId)ResidentialSourcePlan.FitCatalogBlocks(plan);}
 else if(ArchitectureBuilder.Builders.Contains(skill.Builder)){var src=input["source"] as JObject??throw new CadException("NEEDS_SOURCE","Bind DWG source session/document/revision/handles.");string sourceSession=src.Value<string>("sessionId")??session;if(sourceSession!=session)throw new CadException("SOURCE_SESSION","Section source must be in the same AutoCAD session.");string sourceDoc=src.Value<string>("documentId")??throw new CadException("NEEDS_SOURCE","Source document ID required.");string sourceRevision=src.Value<string>("revision")??throw new CadException("NEEDS_SOURCE","Source revision required.");var handles=src["handles"]?.Values<string>().Select(x=>x!).ToList()??new();if(handles.Count!=1)throw new CadException("NEEDS_SOURCE","Select one closed source outline polyline.");var read=await cad.Call(sourceSession,"get_entities",sourceDoc,sourceRevision,new(){["handles"]=JArray.FromObject(handles),["limit"]=25},ct);var entity=((JArray)read["entities"]!).SingleOrDefault()??throw new CadException("NEEDS_SOURCE","Source entity missing.");var geometry=entity["geometry"] as JObject;if(geometry?.Value<string>("kind")!="polyline"||geometry.Value<bool>("closed")!=true)throw new CadException("NEEDS_SOURCE","Source must be a closed XY polyline.");var pts=geometry["points"]!.ToObject<List<Point2>>()!;if(pts.Count!=4)throw new CadException("NEEDS_SOURCE","Rectangular source outline required by this section builder.");double width=Validation.Distance(pts[0],pts[1]),depth=Validation.Distance(pts[0],pts[3]);var built=ArchitectureBuilder.Build(skill.Builder,input,width,depth);plan.Operations=built.Operations;plan.Assumptions=built.Notes;plan.Sources.Add(new(){SessionId=session,DocumentId=sourceDoc,Revision=sourceRevision,Handles=handles});Place(plan,task,false);}
 else {if(skill.Builder=="custom")throw new CadException("NEEDS_INPUT","Use chat or structured operations to create a custom CAD plan.");plan.Operations=Json.Read<List<Operation>>(Json.Write(skill.Workflow));foreach(var op in plan.Operations)foreach(string key in skill.RequiredInputs){if(input[key]!.Type!=JTokenType.Float&&input[key]!.Type!=JTokenType.Integer)throw new CadException("NEEDS_INPUT","Numeric input required: "+key);double number=input[key]!.Value<double>();Validation.Finite(number);if(number<=0||number>100000)throw new CadException("INVALID_INPUT",key);op.Text=op.Text.Replace("{{"+key+"}}",input[key]!.ToString());}Place(plan,task,true);}if(plan.Operations.Any(o=>!skill.RequiredTools.Contains(o.Kind)))throw new CadException("DEPENDENCY_MISSING","Skill chưa khai báo đủ công cụ cho kế hoạch nguồn.");return Save(plan);}
 public async Task<PlanRecord> Custom(string session,string document,string revision,string taskId,List<Operation> operations,CancellationToken ct=default){var(p,t,s)=await Base(session,document,revision,taskId,new(),ct);if(s.Builder!="custom")throw new CadException("SKILL_MISMATCH","Select a CAD_TOOLS task frame for free drawing.");if(operations.Any(o=>!s.RequiredTools.Contains(o.Kind)))throw new CadException("DEPENDENCY_MISSING","Skill chưa khai báo công cụ của thao tác.");p.Operations=operations;if(s.Recipe?.IncludeAxes==true)p.Operations.AddRange(DraftingRules.Axes(s.Recipe));return Save(p);}
 void Place(DrawingPlan p,TaskInfo task,bool normalized){if(task.Scope.Count!=4)throw new CadException("UNSUPPORTED_SCOPE","Placement requires a four-vertex task boundary.");var frameOrigin=task.Scope[0];var origin=task.OutputPoint??frameOrigin;var ux=new Point2(task.Scope[1].X-frameOrigin.X,task.Scope[1].Y-frameOrigin.Y);var vy=new Point2(task.Scope[3].X-frameOrigin.X,task.Scope[3].Y-frameOrigin.Y);double angle=Math.Atan2(ux.Y,ux.X);foreach(var op in p.Operations){op.Points=op.Points.Select(q=>normalized?new Point2(origin.X+q.X*ux.X+q.Y*vy.X,origin.Y+q.X*ux.Y+q.Y*vy.Y):Validation.Rotate(q,origin,angle)).ToList();op.Rotation+=angle;}}
 PlanRecord Save(DrawingPlan plan){var recipe=Store.Skill(plan.SkillId,plan.SkillVersion).Recipe;DraftingRules.Enforce(plan.Operations,recipe,plan.Template);Validation.Plan(plan);plan.TemplateHash=FrameworkPlanHash.ComputeValue(plan.Template,HashHelper,"template");if(!string.IsNullOrEmpty(plan.SkillId))plan.SkillHash=FrameworkPlanHash.ComputeValue(Store.Skill(plan.SkillId,plan.SkillVersion),HashHelper,"skill");var record=new PlanRecord{Plan=plan,Hash=FrameworkPlanHash.Compute(plan,Path.Combine(Path.GetDirectoryName(config.HostExecutable)!,"HashCompat","AICad.HashCompat.exe")),Status="READY",Message="Validated immutable plan; local preview and approval required."};using(Plans.Lock(plan.PlanId)){if(File.Exists(Plans.PathFor(plan.PlanId)))throw new CadException("PLAN_EXISTS","Plan already exists.");Plans.Write(record);}return record;}
 public async Task<PlanRecord> Recreate(string id,CancellationToken ct=default){
  var old=Plans.Read(Json.Id(id));
  if(!new[]{"FAILED","STALE","CANCELLED"}.Contains(old.Status)||old.ExecutionId!=""||old.EntityHandles.Count!=0)throw new CadException("RECREATE_UNSAFE","Chỉ tạo lại kế hoạch chưa từng được thực thi; cần đối soát kế hoạch đã gửi ghi.");
  string helper=Path.Combine(Path.GetDirectoryName(config.HostExecutable)!,"HashCompat","AICad.HashCompat.exe");
  if(old.Hash!=Json.Hash(old.Plan)&&old.Hash!=FrameworkPlanHash.Compute(old.Plan,helper))throw new CadException("PLAN_CHANGED","Kế hoạch cũ đã thay đổi; không thể dùng lại hình học.");
  var d=(await Cad.Documents(ct)).SingleOrDefault(d=>d.SessionId==old.Plan.SessionId&&d.DocumentId==old.Plan.DocumentId)??throw new CadException("SESSION_OFFLINE","Bản vẽ gốc chưa kết nối.");
  var receipt=await Cad.Call(d.SessionId,"inspect_execution",d.DocumentId,d.Revision,new(){["planId"]=id},ct);
  if(receipt.Value<string>("status")!="MISSING_RECEIPT")throw new CadException("RECREATE_UNSAFE","Bản vẽ đã có dấu vết thực thi. Không tự tạo lại.");
  var(p,t,skill)=await Base(d.SessionId,d.DocumentId,d.Revision,old.Plan.TaskId,new(){["_skillVersion"]=old.Plan.SkillVersion,["_templateVersion"]=old.Plan.Template.Version},ct);
  if(skill.Builder!="custom"||old.Plan.Sources.Count!=0)throw new CadException("REPLAN_REQUIRED","Skill này cần kiểm tra lại đầu vào và nguồn trước khi lập kế hoạch mới.");
  if(p.TaskHandle!=old.Plan.TaskHandle||FrameworkPlanHash.ComputeValue(skill,HashHelper,"skill")!=old.Plan.SkillHash||FrameworkPlanHash.ComputeValue(p.Template,HashHelper,"template")!=old.Plan.TemplateHash||Json.Hash(p.Scope)!=Json.Hash(old.Plan.Scope))throw new CadException("TASK_CHANGED","Khung, Skill hoặc Template đã thay đổi. Hãy lập kế hoạch mới từ yêu cầu.");
  p.Operations=Json.Read<List<Operation>>(Json.Write(old.Plan.Operations));
  return Save(p);
 }
 public async Task<JToken> Preview(string id,CancellationToken ct=default){var r=Plans.Read(id);if(r.Status!="READY"&&r.Status!="PREVIEW")throw new CadException("INVALID_STATE",r.Status+": "+r.Message+" Tạo lại kế hoạch nếu chưa thực thi.");var currentSession=cad.Sessions().SingleOrDefault(s=>s.SessionId==r.Plan.SessionId);if(r.Plan.Operations.Any(o=>o.SymbolScale!=null)&&(!Version.TryParse(currentSession?.PluginVersion,out var symbolVersion)||symbolVersion<new Version(0,6,2)))throw new CadException("PLUGIN_UPDATE_REQUIRED","Block ATT cần plugin 0.6.2.");if(r.Plan.AnnotationScales!=null&&(!Version.TryParse(currentSession?.PluginVersion,out var annotationVersion)||annotationVersion<new Version(0,6,1)))throw new CadException("PLUGIN_UPDATE_REQUIRED","Tỷ lệ chú thích cần plugin 0.6.1. Mở lại CAD bằng Mo AI CAD.cmd.");if((r.Plan.Template.Blocks.Any(b=>b.NativeSource!=null)||r.Plan.Template.Font!="txt.shx")&&(!Version.TryParse(currentSession?.PluginVersion,out var currentVersion)||currentVersion<new Version(0,4,0)))throw new CadException("PLUGIN_UPDATE_REQUIRED","Thư viện CAD mới cần plugin 0.4. Lưu bản vẽ và mở lại qua Mo AI CAD.cmd.");if((r.Plan.Operations.Any(o=>o.Kind=="draw_wall"||o.DynamicJson!=null||o.OpeningWidth!=null||o.WallThickness!=null)||r.Plan.Template.Blocks.Any(b=>b.Usage!=null)||r.Plan.Template.Layers.Any(l=>l.Appearance!=null))&&(!Version.TryParse(currentSession?.PluginVersion,out var draftingVersion)||draftingVersion<new Version(0,6,0)))throw new CadException("PLUGIN_UPDATE_REQUIRED","Cấu hình block động và layer chuẩn cần plugin 0.6. Mở lại CAD bằng Mo AI CAD.cmd.");var policy=PreviewPreferences.Load(config.DataRoot);var session=cad.Sessions().SingleOrDefault(s=>s.SessionId==r.Plan.SessionId);if(policy.Mode!="ALWAYS"&&!PreviewPreferences.Supports(session?.PluginVersion??""))throw new CadException("PLUGIN_UPDATE_REQUIRED","Chế độ "+policy.Mode+" đã được lưu. Mở AutoCAD bằng Mo AI CAD.cmd để nạp plugin mới hỗ trợ chế độ này; phiên hiện tại chỉ hỗ trợ ALWAYS.");return await cad.Call(r.Plan.SessionId,"create_preview",r.Plan.DocumentId,r.Plan.DocumentRevision,new(){["planId"]=id},ct);}
 public void Cancel(string id){using(Plans.Lock(id)){var r=Plans.Read(id);if(r.Status!="READY"&&r.Status!="PREVIEW")throw new CadException("INVALID_STATE","Cannot cancel a dispatched/completed plan.");r.Status="CANCELLED";r.Message="Cancelled; no CAD mutation by this plan.";Plans.Write(r);}}
}
